// Isometric art: PNG atlases under game/assets/iso/, described by
// game/assets/iso/manifest.js (generated by the art task's pipeline; see
// docs/iso-art-direction.md). Until a sheet has loaded, or for anything
// without isometric art, the renderer uses the SNES art as a stand-in.
//
// manifest = { tile: { w, h, zPx }, sheets: { name: sheet }, fonts: { name: font } }
// sheet    = { image, frames: { name: [x, y, w, h, ax, ay, fw?, fd?, h?] },
//              anims: { name: { frames: [...], ms } }, ... }
//   (ax, ay): the pixel that lands on the projection of the footprint's
//   center at its base height (a character's feet). fw, fd: the footprint
//   in tiles along x and y; h: height in px. A frame `name.shadow` is that
//   sprite's cast shadow, drawn on the ground first.
// font     = { image, lineHeight, baseline, glyphs: { ch: [x, y, w, h, advance] } }
//
// Characters are matched to content through content.iso.sheets, which pairs
// isometric sheet names with the SNES sheets they draw ({ cheryl: cheryl }). Frame
// names follow the SNES conventions with grid directions (up is up-right on
// screen, right down-right, down down-left, left up-left): <dir>_0 stands,
// anims.walk_<dir> walks, idle_<dir>, poses <pose>_<dir>. A missing
// direction falls back to its screen mirror, flipped: up <-> left, right <-> down.

import manifest from '../../../assets/iso/manifest.js';

const BASE = new URL('../../../assets/iso/', import.meta.url);
export const MIRROR = { up: 'left', left: 'up', right: 'down', down: 'right' };
// Walk frames advance one per this many screen px walked (a tile is ~36 px along a diagonal).
const PX_PER_WALK_FRAME = 6;
const ISO_PX_PER_WORLD_PX = 36 / 16;

const images = new Map(); // file -> { img, ready }
function image(file) {
  let rec = images.get(file);
  if (!rec) {
    if (typeof Image === 'undefined') return { img: null, ready: false }; // Node (the content checker)
    const img = new Image();
    rec = { img, ready: false };
    img.onload = () => { rec.ready = true; };
    img.onerror = () => console.warn(`[iso art] couldn't load ${file}`);
    img.src = new URL(file, BASE).href;
    images.set(file, rec);
  }
  return rec;
}

export class IsoSheet {
  constructor(name, m) {
    this.name = name;
    this.m = m;
    this.cut = new Map();
  }

  // The atlas, loaded on first use.
  get rec() {
    if (!this.recCache || !this.recCache.img) this.recCache = image(this.m.image);
    return this.recCache;
  }

  get ready() {
    return this.rec.ready;
  }

  has(name) {
    return !!this.m.frames[name];
  }

  // The raw frame: { img (the atlas), sx, sy, w, h, ax, ay, fw, fd, hpx }.
  raw(name) {
    const f = this.m.frames[name];
    if (!f) return null;
    const [sx, sy, w, h, ax = w / 2, ay = h, fw = 1, fd = 1, hpx = 0] = f;
    return { img: this.rec.img, sx, sy, w, h, ax, ay, fw, fd, hpx };
  }

  // The frame cut onto its own canvas (for hit tests and flipping), as
  // { img, ax, ay, fw, fd, hpx }; null until the atlas has loaded.
  frame(name) {
    if (!this.ready || !this.has(name)) return null;
    let f = this.cut.get(name);
    if (!f) {
      const r = this.raw(name);
      const c = document.createElement('canvas');
      c.width = r.w;
      c.height = r.h;
      c.getContext('2d', { willReadFrequently: true }).drawImage(r.img, r.sx, r.sy, r.w, r.h, 0, 0, r.w, r.h);
      f = { img: c, ax: r.ax, ay: r.ay, fw: r.fw, fd: r.fd, hpx: r.hpx, name };
      this.cut.set(name, f);
    }
    return f;
  }

  // Frame names of animation `base`: anims[base].frames, else base_0, base_1, ...,
  // else the single frame `base`.
  anim(base) {
    const a = this.m.anims && this.m.anims[base];
    if (a) return a.frames;
    const out = [];
    for (let i = 0; this.has(`${base}_${i}`); i++) out.push(`${base}_${i}`);
    if (!out.length && this.has(base)) out.push(base);
    return out;
  }

  // The frame of `base` showing `ms` after it started (loops).
  frameAt(base, ms) {
    const names = this.anim(base);
    if (!names.length) return null;
    const a = this.m.anims && this.m.anims[base];
    const d = a ? a.ms : this.m.durations?.[base] ?? 150;
    if (Array.isArray(d)) {
      const total = d.reduce((s, x) => s + x, 0) || 1;
      let t = ((ms % total) + total) % total;
      for (let i = 0; i < names.length; i++) {
        const di = d[i % d.length];
        if (t < di) return this.frame(names[i]);
        t -= di;
      }
      return this.frame(names[names.length - 1]);
    }
    return this.frame(names[Math.floor(ms / (d || 150)) % names.length]);
  }
}

const sheets = new Map(Object.entries(manifest.sheets || {}).map(([name, m]) => [name, new IsoSheet(name, m)]));

export function isoSheet(name) {
  return sheets.get(name) || null;
}

export const isoFonts = manifest.fonts || {};
export const fontImage = (font) => image(font.image);

// The isometric frame for an entity's current state, as { img, ax, ay,
// flip, shadow }, or null (draw the SNES sprite instead). Mirrors
// entity.currentFrame()'s choices.
const bySnes = new WeakMap(); // SNES sheet object -> isometric sheet names

// Content says which isometric sheet draws which SNES sheet:
// content.iso.sheets = { isoSheetName: snesSheet }.
let aliases = {};
export function bindSnesSheets(map = {}, frameAliases = {}) {
  for (const [name, list] of Object.entries(map)) {
    // One isometric sheet may stand in for several SNES sheets (fx and fx_mist).
    for (const snes of [list].flat()) {
    if (!snes) continue;
    // Several isometric sheets may draw one shared SNES sheet's objects (the cat, from props).
    bySnes.set(snes, [...(bySnes.get(snes) || []), name]);
    }
  }
  aliases = frameAliases;
}

export function isoFrameFor(e) {
  const names = (e.sprite && e.sprite.sheet && bySnes.get(e.sprite.sheet)) || [];
  for (const name of names) {
    const s = sheets.get(name);
    if (!s || !s.ready) continue;
    const f = frameIn(e, s, name);
    if (f) return f;
  }
  return null;
}

function frameIn(e, s, name) {
  const ms = e.animMs + e.phase;
  const withShadow = (f, flip) => f && { ...f, flip, shadow: s.frame(`${f.name}.shadow`) };
  const pick = (fn) => {
    let f = fn(e.facing);
    if (f) return withShadow(f, false);
    if ((f = fn(MIRROR[e.facing]))) return withShadow(f, true);
    return null;
  };
  if (e.pose) {
    const p = e.pose;
    const r = pick((d) => s.frameAt(`${p}_${d}`, e.poseMs));
    if (r) return r;
    const f = s.frameAt(p, e.poseMs);
    if (f) return withShadow(f, false);
  }
  if (!e.directional) {
    const alias = aliases[name] && aliases[name][e.sprite.frame];
    if (alias) {
      const r = pick((d) => s.frameAt(alias.replace('{dir}', d), ms));
      if (r) return r;
    }
    return withShadow(s.frameAt(e.sprite.frame, ms), false);
  }
  if (e.moving || e.walkPx > 0) {
    const r = pick((d) => {
      const names = s.anim(`walk_${d}`);
      if (!names.length) return null;
      return s.frame(names[Math.floor((e.walkPx * ISO_PX_PER_WORLD_PX) / PX_PER_WALK_FRAME) % names.length]);
    });
    if (r) return r;
  }
  return pick((d) => s.frame(`${d}_0`) || s.frameAt(`idle_${d}`, ms));
}

// The isometric frame for an SNES sheet's frame or animation (an effect's
// sprite), as { img, ax, ay }, or null.
export function isoFrameForSheet(snes, frame, ms) {
  for (const name of bySnes.get(snes) || []) {
    const s = sheets.get(name);
    if (!s || !s.ready) continue;
    const alias = aliases[name] && aliases[name][frame];
    const f = s.frameAt(alias || frame, ms);
    if (f) return f;
  }
  return null;
}
